"""Frozen target DDL for changes_migration (CHANGES_TO_DIGEST endpoint)."""

from __future__ import annotations

TARGET_TABLE_DDLS: dict[str, str] = {
    "changes": "CREATE TABLE changes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  kind TEXT NOT NULL,\n  label TEXT,\n  spec TEXT NOT NULL DEFAULT '{}',\n  undo_info TEXT,\n  status TEXT NOT NULL DEFAULT 'applied',\n  change_order INTEGER,\n  publication_closed INTEGER NOT NULL DEFAULT 1 CHECK(publication_closed IN (0,1)),\n  redo_eligible INTEGER NOT NULL DEFAULT 1 CHECK(redo_eligible IN (0,1)),\n  barrier INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n)",
    "base_cell_producers": "CREATE TABLE base_cell_producers (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  stage_id TEXT NOT NULL UNIQUE CHECK (length(trim(stage_id)) > 0),\n  change_id INTEGER REFERENCES changes(id) ON DELETE RESTRICT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n)",
    "runs": "CREATE TABLE runs (\n  -- AUTOINCREMENT is intentional: paid row-effect checkpoints outlive a\n  -- compacted run and retain its numeric id as their durable group key.  A\n  -- reused ROWID would make that orphan look attached to an unrelated future\n  -- run and could replay/refuse the wrong provider effect.\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  change_id INTEGER NOT NULL REFERENCES changes(id),\n  sheet_id INTEGER NOT NULL REFERENCES sheets(id),\n  -- Content-free immutable identity survives payload purges. NULL is a root\n  -- (including migrated historical singleton runs); retries name that root.\n  execution_root_run_id INTEGER REFERENCES runs(id) ON DELETE RESTRICT,\n  -- Canonical action identity. There is deliberately no persisted runner\n  -- implementation alias or compatibility column.\n  action_kind TEXT NOT NULL,\n  action_version TEXT NOT NULL DEFAULT '1',\n  model TEXT,\n  prompt_hash TEXT,\n  params TEXT NOT NULL DEFAULT '{}',\n  -- Optional active-document telemetry is separate from canonical action inputs.\n  work_progress TEXT CHECK (\n    work_progress IS NULL\n    OR (json_valid(work_progress) AND json_type(work_progress)='object')\n  ),\n  status TEXT NOT NULL DEFAULT 'running',  -- running|completed|failed|cancelled\n  -- Durable cooperative cancellation INTENT. This is deliberately separate\n  -- from ``status``: a live writer keeps the run ``running`` until its fenced\n  -- terminal transaction closes the run, receipt, attempt, and claim together.\n  cancel_requested_at TEXT,\n  total_rows INTEGER NOT NULL DEFAULT 0,\n  completed_rows INTEGER NOT NULL DEFAULT 0,\n  failed_rows INTEGER NOT NULL DEFAULT 0,\n  cost_estimate REAL,\n  -- Projection of this run's model_calls facts (RunResultStore.\n  -- _project_cost_actual, the one writer): SUM of live provider_cost_usd,\n  -- cache facts excluded. NULL means at least one live call's provider cost\n  -- is unknown — an honest cannot-say, never rendered as $0.\n  cost_actual REAL DEFAULT 0,\n  started_at TEXT NOT NULL DEFAULT (datetime('now')),\n  finished_at TEXT,\n  -- Human review workflow state is independent of execution completion.\n  -- NULL means open; a timestamp means the reviewer marked this run complete.\n  review_completed_at TEXT,\n  -- RUN_REVIEW_RUN_COLUMNS_BEGIN\n  -- Compact review projections. The result rows remain authority; these\n  -- counters are rebuilt once when a run terminalizes and updated by exact\n  -- review transitions. ``resolved`` includes migrated verified results whose\n  -- historical human decision is unknown, while field-level reviewed counts\n  -- below count only a non-NULL review_decision.\n  review_stats_ready INTEGER NOT NULL DEFAULT 0\n    CHECK (review_stats_ready IN (0,1)),\n  review_bundle_count INTEGER NOT NULL DEFAULT 0\n    CHECK (review_bundle_count >= 0),\n  review_resolved_bundle_count INTEGER NOT NULL DEFAULT 0\n    CHECK (\n      review_resolved_bundle_count >= 0\n      AND review_resolved_bundle_count <= review_bundle_count\n    ),\n  -- RUN_REVIEW_RUN_COLUMNS_END\n  -- Code identity of the worker process that claimed and executed this run\n  -- (worker-version-guard-v1: frisket.worker_version.code_version(), stamped\n  -- by the project.run/action.run handlers). NULL for runs never claimed off\n  -- a queue (synchronous/local runs) or written before this column existed.\n  worker_version TEXT,\n  -- The attempt this run last claimed, written inside the\n  -- owned claim transaction. Reconsent reads it under the same lock and\n  -- refuses while it names a live 'dispatching' attempt, which is what makes\n  -- \"one attempt = one authorization decision\" structural rather than\n  -- advisory. NULL until a first claim commits.\n  current_attempt_id TEXT REFERENCES execution_attempts(id),\n  -- Halt state as columns rather than keys inside `params`.\n  -- Relocation, not retirement: `begin_run_resume` clears them, a refused\n  -- resume restores them verbatim (`revert_run_resume`), and\n  -- `halted_reason`-without-`halted_code` stays representable so the legacy\n  -- circuit breaker's halts are not reclassified as typed invocation halts.\n  halted_code TEXT,\n  halted_reason TEXT,\n  -- The hosted funding/edition context the action\n  -- boundary attaches after run creation, off `params` so `start_run`'s\n  -- INSERT is the spec's writer.\n  edition_run_context TEXT,\n  consent_principal TEXT\n)",
    "import_sessions": "CREATE TABLE import_sessions (\n  id TEXT PRIMARY KEY,\n  sheet_id INTEGER REFERENCES sheets(id) ON DELETE SET NULL,\n  producer_id INTEGER REFERENCES base_cell_producers(id) ON DELETE SET NULL,\n  change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE RESTRICT,\n  receipt_id TEXT REFERENCES receipts(id) ON DELETE SET NULL,\n  writer_authority TEXT NOT NULL,\n  cursor INTEGER NOT NULL DEFAULT 0 CHECK (cursor >= 0),\n  committed_rows INTEGER NOT NULL DEFAULT 0 CHECK (committed_rows >= 0),\n  committed_bytes INTEGER NOT NULL DEFAULT 0 CHECK (committed_bytes >= 0),\n  state TEXT NOT NULL CHECK (\n    state IN ('active','paused','cancelled','kept','completed','removed')\n  ),\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n)",
    "generated_column_claims": "CREATE TABLE generated_column_claims (\n  id TEXT PRIMARY KEY,\n  sheet_id INTEGER NOT NULL REFERENCES sheets(id) ON DELETE CASCADE,\n  column_id INTEGER REFERENCES columns(id) ON DELETE CASCADE,\n  output_name TEXT NOT NULL,\n  run_id INTEGER REFERENCES runs(id) ON DELETE SET NULL,\n  change_id INTEGER REFERENCES changes(id) ON DELETE SET NULL,\n  receipt_id TEXT REFERENCES receipts(id) ON DELETE SET NULL,\n  job_id INTEGER,\n  action_kind TEXT NOT NULL,\n  mode TEXT NOT NULL DEFAULT 'replace',\n  expected_current_run_id INTEGER,\n  claim_token TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'active',\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  renewed_at TEXT,\n  lease_expires_at TEXT,\n  released_at TEXT,\n  details TEXT NOT NULL DEFAULT '{}'\n)",
    "prepared_page_versions": "CREATE TABLE prepared_page_versions (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  source_artifact_id INTEGER REFERENCES source_artifacts(id) ON DELETE SET NULL,\n  page_number INTEGER NOT NULL CHECK (page_number>0),\n  prepared_text TEXT NOT NULL,\n  content_hash TEXT NOT NULL CHECK (\n    length(content_hash)=71 AND substr(content_hash,1,7)='sha256:'\n  ),\n  positions_json TEXT CHECK (positions_json IS NULL OR json_valid(positions_json)),\n  producing_change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE RESTRICT\n)",
    "prepared_content_sets": "CREATE TABLE prepared_content_sets (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  source_artifact_id INTEGER REFERENCES source_artifacts(id) ON DELETE SET NULL,\n  producing_change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE RESTRICT\n)",
    "edits": "CREATE TABLE edits (\n  change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE CASCADE,\n  row_id INTEGER NOT NULL,\n  column_id INTEGER NOT NULL,\n  value_kind TEXT NOT NULL CHECK (value_kind IN (\n    'null','text','integer','real','boolean','json','bigint','legacy_invalid',\n    'prepared_content_ref'\n  )),\n  value,\n  PRIMARY KEY (change_id, row_id, column_id),\n  CHECK (\n    (value_kind='null' AND value IS NULL)\n    OR (value_kind='text' AND typeof(value)='text')\n    OR (value_kind='integer' AND typeof(value)='integer')\n    OR (value_kind='real' AND typeof(value)='real'\n        AND value=value AND abs(value)<=1.7976931348623157e308)\n    OR (value_kind='boolean' AND typeof(value)='integer' AND value IN (0,1))\n    OR (value_kind='json' AND typeof(value)='text' AND json_valid(value))\n    OR (value_kind='bigint' AND typeof(value)='text')\n    OR (value_kind='legacy_invalid' AND typeof(value)='text')\n    OR (value_kind='prepared_content_ref' AND typeof(value)='integer' AND value>0)\n  )\n) WITHOUT ROWID",
    "current_cells": "CREATE TABLE current_cells (\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  retrieval_revision INTEGER NOT NULL CHECK (retrieval_revision > 0),\n  origin_kind TEXT NOT NULL CHECK (\n    origin_kind IN ('source_cell', 'run_result', 'manual_edit', 'copied_result')\n  ),\n  origin_change_id INTEGER REFERENCES changes(id) ON DELETE CASCADE,\n  origin_run_id INTEGER REFERENCES runs(id) ON DELETE CASCADE,\n  base_producer_id INTEGER REFERENCES base_cell_producers(id) ON DELETE RESTRICT,\n  validity TEXT NOT NULL CHECK (validity IN ('valid', 'missing', 'invalid')),\n  inline_value_kind TEXT CHECK (inline_value_kind IN (\n    'null','text','integer','real','boolean','bigint'\n  )),\n  inline_value,\n  outcome TEXT NOT NULL DEFAULT 'completed' CHECK(outcome IN ('completed','pending','failed','not_completed')),\n  CHECK (\n    (inline_value_kind IS NULL AND inline_value IS NULL)\n    OR (inline_value_kind='null' AND inline_value IS NULL)\n    OR (inline_value_kind='text' AND typeof(inline_value)='text')\n    OR (inline_value_kind='integer' AND typeof(inline_value)='integer')\n    OR (inline_value_kind='real' AND typeof(inline_value)='real'\n        AND inline_value=inline_value\n        AND abs(inline_value)<=1.7976931348623157e308)\n    OR (inline_value_kind='boolean' AND typeof(inline_value)='integer'\n        AND inline_value IN (0,1))\n    OR (inline_value_kind='bigint' AND typeof(inline_value)='text')\n  ),\n  CHECK (\n    (\n      origin_kind='source_cell'\n      AND origin_change_id IS NULL\n      AND origin_run_id IS NULL\n    )\n    OR (\n      origin_kind='run_result'\n      AND origin_change_id IS NOT NULL\n      AND origin_run_id IS NOT NULL\n      AND base_producer_id IS NULL\n    )\n    OR (\n      origin_kind='copied_result'\n      AND origin_change_id IS NOT NULL\n      AND base_producer_id IS NULL\n    )\n    OR (\n      origin_kind='manual_edit'\n      AND origin_change_id IS NOT NULL\n      AND origin_run_id IS NULL\n      AND base_producer_id IS NULL\n    )\n  )\n)",
    "feed_checks": "CREATE TABLE feed_checks (\n  id INTEGER PRIMARY KEY,\n  feed_id INTEGER NOT NULL REFERENCES feeds(id) ON DELETE CASCADE,\n  change_id INTEGER REFERENCES changes(id) ON DELETE SET NULL,\n  receipt_id TEXT REFERENCES receipts(id) ON DELETE SET NULL,\n  status TEXT NOT NULL DEFAULT 'ok',     -- ok | error\n  new_rows INTEGER NOT NULL DEFAULT 0,\n  skipped_rows INTEGER NOT NULL DEFAULT 0,\n  changed_rows INTEGER NOT NULL DEFAULT 0,\n  revisions INTEGER NOT NULL DEFAULT 0,\n  error TEXT,\n  cursor_before TEXT,\n  cursor_after TEXT,\n  duration_ms INTEGER,\n  warning_count INTEGER NOT NULL DEFAULT 0,\n  cost_micro INTEGER NOT NULL DEFAULT 0,\n  summary_json TEXT NOT NULL DEFAULT '{}',\n  started_at TEXT NOT NULL DEFAULT (datetime('now')),\n  finished_at TEXT\n)",
    "views": "CREATE TABLE views (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sheet_id INTEGER REFERENCES sheets(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  spec TEXT NOT NULL DEFAULT '{}',\n  change_id INTEGER REFERENCES changes(id),\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n)",
    "cell_baseline": "CREATE TABLE cell_baseline (\n  row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  origin_kind TEXT NOT NULL,\n  origin_change_id INTEGER REFERENCES changes(id),\n  origin_run_id INTEGER REFERENCES runs(id),\n  base_producer_id INTEGER REFERENCES base_cell_producers(id),\n  PRIMARY KEY(column_id,row_id,origin_kind)\n)",
    "materialized_row_sources": "CREATE TABLE materialized_row_sources (\n  materialized_row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  source_row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  source_sheet_id INTEGER NOT NULL REFERENCES sheets(id) ON DELETE CASCADE,\n  change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE CASCADE,\n  role TEXT NOT NULL CHECK (\n    role IN (\n      'edge_source', 'edge_target', 'aggregate_source', 'join_left', 'join_right'\n    )\n  ),\n  PRIMARY KEY (materialized_row_id, source_row_id, role, change_id)\n)",
    "document_text_manual_pins": "CREATE TABLE document_text_manual_pins (\n  edit_change_id INTEGER NOT NULL,\n  row_id INTEGER NOT NULL,\n  text_column_id INTEGER NOT NULL,\n  prepared_ref_id INTEGER NOT NULL\n    REFERENCES prepared_content_refs(id) ON DELETE RESTRICT,\n  PRIMARY KEY (edit_change_id,row_id,text_column_id),\n  FOREIGN KEY (edit_change_id,row_id,text_column_id)\n    REFERENCES edits(change_id,row_id,column_id) ON DELETE CASCADE\n) WITHOUT ROWID",
    "copied_result_outcomes": "CREATE TABLE copied_result_outcomes (\n  change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE RESTRICT,\n  row_id INTEGER NOT NULL REFERENCES rows(id) ON DELETE CASCADE,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  source_run_id INTEGER,\n  source_row_id INTEGER,\n  source_column_id INTEGER,\n  review_state TEXT NOT NULL DEFAULT 'unreviewed',\n  review_decision TEXT CHECK(review_decision IN ('accept','reject','reject_clear','edit')),\n  review_note TEXT,\n  PRIMARY KEY(change_id,row_id,column_id),\n  FOREIGN KEY(source_run_id,source_row_id,source_column_id)\n    REFERENCES results(run_id,row_id,column_id) ON DELETE RESTRICT,\n  CHECK ((source_run_id IS NULL AND source_row_id IS NULL AND source_column_id IS NULL)\n    OR (source_run_id IS NOT NULL AND source_row_id IS NOT NULL AND source_column_id IS NOT NULL))\n) WITHOUT ROWID",
    "consumed_source_bundles": "CREATE TABLE consumed_source_bundles (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  capture_key TEXT NOT NULL UNIQUE,\n  owner_change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE CASCADE,\n  run_id INTEGER REFERENCES runs(id) ON DELETE CASCADE,\n  row_id INTEGER REFERENCES rows(id) ON DELETE CASCADE,\n  output_sheet_id INTEGER NOT NULL REFERENCES sheets(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL CHECK(kind IN ('row','aggregate')),\n  input_fingerprint TEXT NOT NULL,\n  capture_json TEXT NOT NULL CHECK(json_valid(capture_json)),\n  state TEXT NOT NULL CHECK(state IN ('fresh','stale','unknown','checking')),\n  checked_revisions_json TEXT NOT NULL CHECK(json_valid(checked_revisions_json))\n)",
    "column_descriptor_changes": "CREATE TABLE column_descriptor_changes (\n  change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE CASCADE,\n  column_id INTEGER NOT NULL REFERENCES columns(id) ON DELETE CASCADE,\n  property TEXT NOT NULL CHECK(property IN ('type','format','semantic_type')),\n  PRIMARY KEY(column_id,property,change_id)\n)",
    "structural_changes": "CREATE TABLE structural_changes (\n  change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL CHECK(kind IN ('row','column','sheet')),\n  object_id INTEGER NOT NULL,\n  before_visible INTEGER NOT NULL CHECK(before_visible IN (0,1)),\n  after_visible INTEGER NOT NULL CHECK(after_visible IN (0,1)),\n  PRIMARY KEY(kind,object_id,change_id)\n)",
    "result_judgment_changes": "CREATE TABLE result_judgment_changes (\n change_id INTEGER NOT NULL REFERENCES changes(id) ON DELETE CASCADE,\n target TEXT NOT NULL,\n property TEXT NOT NULL CHECK(property IN ('state','decision','note')),\n PRIMARY KEY(target,property,change_id)\n)",
}

