TARGET_TRIGGER_DDLS: dict[str, str] = {
    "trg_results_effect_insert_open_generation": "CREATE TRIGGER trg_results_effect_insert_open_generation\nBEFORE INSERT ON results\nWHEN NEW.publication_effect IS NOT NULL\n  AND NOT EXISTS (\n    SELECT 1\n    FROM run_output_generations generation\n    JOIN runs run ON run.id = generation.run_id\n    JOIN changes ch ON ch.id = run.change_id\n    WHERE generation.run_id = NEW.run_id\n      AND generation.column_id = NEW.column_id\n      AND generation.state IN ('active', 'staged')\n      AND ch.status = 'applied'\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'publication effect requires an open applied generation');\nEND",
    "trg_results_effect_update_open_generation": "CREATE TRIGGER trg_results_effect_update_open_generation\nBEFORE UPDATE OF publication_effect ON results\nWHEN OLD.publication_effect IS NULL\n  AND NEW.publication_effect IS NOT NULL\n  AND NOT EXISTS (\n    SELECT 1\n    FROM run_output_generations generation\n    JOIN runs run ON run.id = generation.run_id\n    JOIN changes ch ON ch.id = run.change_id\n    WHERE generation.run_id = NEW.run_id\n      AND generation.column_id = NEW.column_id\n      AND generation.state IN ('active', 'staged')\n      AND ch.status = 'applied'\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'publication effect requires an open applied generation');\nEND",
    "trg_results_semantic_update_open_generation": "CREATE TRIGGER trg_results_semantic_update_open_generation\nBEFORE UPDATE OF value_kind, value, tokens_in, tokens_out, confidence, justification,\n  warnings, error, error_code, outcome, publication_effect ON results\nWHEN NEW.publication_effect IS NOT NULL\n  AND (\n    NEW.run_id IS NOT OLD.run_id\n    OR NEW.row_id IS NOT OLD.row_id\n    OR NEW.column_id IS NOT OLD.column_id\n    OR NEW.value_kind IS NOT OLD.value_kind\n    OR NEW.value IS NOT OLD.value\n    OR NEW.tokens_in IS NOT OLD.tokens_in\n    OR NEW.tokens_out IS NOT OLD.tokens_out\n    OR NEW.confidence IS NOT OLD.confidence\n    OR NEW.justification IS NOT OLD.justification\n    OR NEW.warnings IS NOT OLD.warnings\n    OR NEW.error IS NOT OLD.error\n    OR NEW.error_code IS NOT OLD.error_code\n    OR NEW.outcome IS NOT OLD.outcome\n    OR NEW.publication_effect IS NOT OLD.publication_effect\n  )\n  AND NOT EXISTS (\n    SELECT 1\n    FROM run_output_generations generation\n    JOIN runs run ON run.id = generation.run_id\n    JOIN changes ch ON ch.id = run.change_id\n    WHERE generation.run_id = NEW.run_id\n      AND generation.column_id = NEW.column_id\n      AND generation.state IN ('active', 'staged')\n      AND ch.status = 'applied'\n  )\nBEGIN\n  SELECT RAISE(ABORT, 'publication effect requires an open applied generation');\nEND",
    "trg_run_output_generations_delete_discarded_only": "CREATE TRIGGER trg_run_output_generations_delete_discarded_only\nBEFORE DELETE ON run_output_generations\nWHEN EXISTS (\n  SELECT 1\n  FROM runs run\n  JOIN changes ch ON ch.id = run.change_id\n  WHERE run.id = OLD.run_id\n    AND ch.status <> 'discarded'\n)\nBEGIN\n  SELECT RAISE(ABORT, 'output generation can be deleted only after change discard');\nEND",
    "trg_cell_result_heads_require_publishable_result": "CREATE TRIGGER trg_cell_result_heads_require_publishable_result\nBEFORE INSERT ON cell_result_heads\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM results result\n  JOIN run_output_generations generation\n    ON generation.run_id = result.run_id\n   AND generation.column_id = result.column_id\n  JOIN runs run ON run.id = generation.run_id\n  JOIN changes ch ON ch.id = run.change_id\n  WHERE result.run_id = NEW.run_id\n    AND result.row_id = NEW.row_id\n    AND result.column_id = NEW.column_id\n    AND result.publication_effect IN ('publish_value','publish_null','publish_error')\n    AND generation.state IN ('active', 'staged', 'sealed')\n    AND ch.status = 'applied'\n)\nBEGIN\n  SELECT RAISE(ABORT, 'cell head requires an applied publishable result');\nEND",
    "trg_cell_result_heads_update_publishable_result": "CREATE TRIGGER trg_cell_result_heads_update_publishable_result\nBEFORE UPDATE ON cell_result_heads\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM results result\n  JOIN run_output_generations generation\n    ON generation.run_id = result.run_id\n   AND generation.column_id = result.column_id\n  JOIN runs run ON run.id = generation.run_id\n  JOIN changes ch ON ch.id = run.change_id\n  WHERE result.run_id = NEW.run_id\n    AND result.row_id = NEW.row_id\n    AND result.column_id = NEW.column_id\n    AND result.publication_effect IN ('publish_value','publish_null','publish_error')\n    AND generation.state IN ('active', 'staged', 'sealed')\n    AND ch.status = 'applied'\n)\nBEGIN\n  SELECT RAISE(ABORT, 'cell head requires an applied publishable result');\nEND",
    "run_execution_root_immutable": "CREATE TRIGGER run_execution_root_immutable\nBEFORE UPDATE OF execution_root_run_id ON runs\nWHEN NEW.execution_root_run_id IS NOT OLD.execution_root_run_id\nBEGIN\n  SELECT RAISE(ABORT,'execution root identity is immutable');\nEND",
    "run_execution_root_valid": "CREATE TRIGGER run_execution_root_valid\nBEFORE INSERT ON runs\nWHEN NEW.execution_root_run_id IS NOT NULL AND NOT EXISTS (\n  SELECT 1 FROM runs root WHERE root.id=NEW.execution_root_run_id\n    AND root.execution_root_run_id IS NULL\n    AND root.sheet_id=NEW.sheet_id AND root.action_kind=NEW.action_kind\n)\nBEGIN\n  SELECT RAISE(ABORT,'execution root must name an original run of this action and sheet');\nEND",
    "trg_text_surfaces_no_update": "CREATE TRIGGER trg_text_surfaces_no_update\nBEFORE UPDATE ON text_surfaces\nBEGIN\n  SELECT RAISE(ABORT, 'text surfaces are append-only');\nEND",
}

