        "CREATE VIEW cell_contributions AS\nSELECT cell.row_id,cell.column_id,'source_cell' AS origin_kind,\n       NULL AS origin_change_id,NULL AS origin_run_id,cell.producer_id AS base_producer_id,\n       ch.change_order,1 AS publication_closed,0 AS edit_supersession\nFROM cells cell JOIN base_cell_producers producer ON producer.id=cell.producer_id\nJOIN changes ch ON ch.id=producer.change_id\nWHERE ch.status='applied' AND ch.change_order IS NOT NULL\nUNION ALL\nSELECT scope.row_id,generation.column_id,'run_result',run.change_id,run.id,NULL,\n       ch.change_order,ch.publication_closed,\n       CASE WHEN generation.write_mode!='replace_scope' THEN 0\n            WHEN json_type(ch.undo_info,'$.column_types_after.\"'||generation.column_id||'\"') IS NOT NULL OR json_type(ch.undo_info,'$.column_formats_after.\"'||generation.column_id||'\"') IS NOT NULL OR json_type(ch.undo_info,'$.column_semantic_types_after.\"'||generation.column_id||'\"') IS NOT NULL THEN 2 ELSE 1 END\nFROM run_output_generations generation JOIN runs run ON run.id=generation.run_id\nJOIN changes ch ON ch.id=run.change_id JOIN run_rows scope ON scope.run_id=run.id\nWHERE ch.status='applied' AND ch.change_order IS NOT NULL\nAND generation.state!='staged'\nAND NOT EXISTS (SELECT 1 FROM json_each(COALESCE(json_extract(\n ch.undo_info,'$.unpublished_generation_columns'),'[]')) unpublished\n WHERE CAST(unpublished.value AS INTEGER)=generation.column_id)\nAND NOT EXISTS (SELECT 1 FROM results retained WHERE retained.run_id=run.id\n AND retained.row_id=scope.row_id AND retained.column_id=generation.column_id\n AND retained.publication_effect='retain')\nUNION ALL\nSELECT edit.row_id,edit.column_id,'manual_edit',edit.change_id,NULL,NULL,\n       ch.change_order,1,CASE WHEN ch.kind='review.decision' AND json_extract(ch.spec,'$.params.decision')='reject_clear' THEN 1 ELSE 2 END\nFROM edits edit JOIN changes ch ON ch.id=edit.change_id\nWHERE ch.status='applied' AND ch.change_order IS NOT NULL\nUNION ALL\nSELECT copy.row_id,copy.column_id,'copied_result',copy.change_id,copy.source_run_id,NULL,\n       ch.change_order,1,CASE WHEN json_type(ch.undo_info,'$.column_types_after.\"'||copy.column_id||'\"') IS NOT NULL OR json_type(ch.undo_info,'$.column_formats_after.\"'||copy.column_id||'\"') IS NOT NULL OR json_type(ch.undo_info,'$.column_semantic_types_after.\"'||copy.column_id||'\"') IS NOT NULL THEN 2 ELSE 1 END\nFROM copied_result_outcomes copy JOIN changes ch ON ch.id=copy.change_id\nWHERE ch.status='applied' AND ch.change_order IS NOT NULL\nUNION ALL\nSELECT baseline.row_id,baseline.column_id,baseline.origin_kind,baseline.origin_change_id,\n       baseline.origin_run_id,baseline.base_producer_id,0,1,\n       CASE WHEN baseline.origin_kind!='manual_edit' THEN 0\n            WHEN EXISTS (SELECT 1 FROM changes ch WHERE ch.id=baseline.origin_change_id AND ch.kind='review.decision' AND json_extract(ch.spec,'$.params.decision')='reject_clear') THEN 1 ELSE 2 END\nFROM cell_baseline baseline",
